// Hubla (v2) -> public.hubla_reembolsos. Contrato: docs/contrato-dados.md (hubla_reembolsos).
// Eventos: refund_request.* e invoice.refunded. Chave: invoice_id, event_type.
const body = ($json.body && typeof $json.body === 'object') ? $json.body : {};
const get = (o, p) => p.split('.').reduce((a, k) => (a && typeof a === 'object') ? a[k] : undefined, o);
const first = (...ps) => { for (const p of ps) { const v = get(body, p); if (v !== undefined && v !== null && !(typeof v === 'string' && v.trim() === '')) return v; } return null; };
const txt = (v) => (v === null || typeof v === 'object') ? null : (String(v).trim() || null);
const int = (v) => { if (v === null || v === '') return null; const n = Number(v); return Number.isFinite(n) ? Math.round(n) : null; };
const bool = (v) => v === true || v === 'true' ? true : (v === false || v === 'false' ? false : null);
const ts = (v) => { const s = txt(v); if (!s) return null; const dt = DateTime.fromISO(s.replace(' ', 'T'), { zone: 'UTC-3' }); return dt.isValid ? dt.toISO() : null; };
const nomeUser = () => txt(first('event.user.name', 'event.user.fullName')) ?? (txt([first('event.user.firstName'), first('event.user.lastName')].filter(Boolean).join(' ')));

const tipo = txt(body.type);
const invoiceId = txt(first('event.invoice.id', 'event.refundRequest.invoiceId', 'event.refund.invoiceId', 'event.invoiceId'));
if (!invoiceId || !tipo) throw new Error('Hubla Reembolsos: invoice_id ou type ausente (type ' + (tipo ?? 'ausente') + '). Confira os eventos marcados na regra da Hubla.');
const rr = (k) => first('event.refundRequest.' + k, 'event.refund.' + k);
const utm = (k) => txt(first('event.invoice.paymentSession.utm.' + k, 'event.paymentSession.utm.' + k, 'event.invoice.utm.' + k, 'event.utm.' + k));

return { json: {
  invoice_id: invoiceId,
  event_type: tipo,
  refund_id: txt(rr('id')),
  refund_status: txt(rr('status')),
  refund_description: txt(rr('description')),
  refund_feedback: txt(rr('feedback')),
  is_auto_accepted: bool(rr('isAutoAccepted')),
  product_id: txt(first('event.product.id', 'event.products.0.id', 'event.invoice.product.id')),
  product_name: txt(first('event.product.name', 'event.products.0.name', 'event.invoice.product.name')),
  offer_id: txt(first('event.products.0.offers.0.id', 'event.offer.id', 'event.invoice.offer.id')),
  offer_name: txt(first('event.products.0.offers.0.name', 'event.offer.name', 'event.invoice.offer.name')),
  payer_nome: nomeUser(),
  payer_email: txt(first('event.user.email')),
  payer_telefone: txt(first('event.user.phone')),
  payment_method: txt(first('event.invoice.paymentMethod')),
  total_cents: int(first('event.invoice.amount.totalCents', 'event.refundRequest.amountCents', 'event.refund.amountCents')),
  utm_source: utm('source'), utm_medium: utm('medium'), utm_campaign: utm('campaign'), utm_content: utm('content'), utm_term: utm('term'),
  sale_date: ts(first('event.invoice.saleDate', 'event.invoice.paidAt')),
  refund_created_at: ts(rr('createdAt')),
  refunded_at: ts(rr('acceptedAt') ?? rr('refundedAt') ?? (tipo === 'invoice.refunded' ? first('event.invoice.modifiedAt', 'event.invoice.updatedAt') : null)),
  raw_payload: body
} };
